-- 2026-11-11 知识库精修：顶层序号按“目”从 1 重新开始
-- 仅处理原首号不是 1 的 92 个条目；新 revision 保留旧 revision 可回滚。
-- 备份：private/agy-context/kb-published-before-renumber-20261111.tsv
begin;
create temp table _kb_renumber_20261111 (node_id integer primary key, blocks jsonb not null) on commit drop;

do $$
declare
  r record;
  old_rev record;
  v_rev integer;
  n integer;
begin
  select count(*) into n from _kb_renumber_20261111;
  if n <> 92 then
    raise exception '预期 92 条，实际 %', n;
  end if;
  for r in select node_id, blocks from _kb_renumber_20261111 order by node_id loop
    select rev_no, html, search_text, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then
      raise exception '节点 % 找不到已发布 revision', r.node_id;
    end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    values (r.node_id, v_rev, r.blocks, old_rev.html, old_rev.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
  select count(*) into n
    from _kb_renumber_20261111 t
    join kb_entry e on e.node_id = t.node_id
   where e.published_rev <> (select max(rev_no) from kb_revision x where x.node_id = t.node_id);
  if n <> 0 then
    raise exception '有 % 个节点发布版本未指向最新 revision', n;
  end if;
end $$;
commit;
